Q: How to get Firebase hosting emulator to serve a Vite dev server locally? A: <p>I am surprised there is no plugin to pick this up.</p>
<p>I use the <code>server.proxy</code> option in vite config to roughly manage rewrites like firebase hosting does.</p>
<p>It isn't 1 to 1 but is good enough for the common use case.</p>
<pre class="lang-js prettyprint-override"><code>import { readFileSync } from &quot;fs&quot;;
import globToRegExp from &quot;glob-to-regexp&quot;;
import { defineConfig, type ProxyOptions } from &quot;vite&quot;;
import { emulators, hosting } from &quot;./firebase.json&quot;;

const firebaseConfig = JSON.parse(readFileSync(&quot;./.firebaserc&quot;).toString());
const projectId = firebaseConfig.projects.default;
const functionRewrites = Object.fromEntries(
  hosting.rewrites
    .filter((def) =&gt; !!def.function)
    .map(
      ({
        source,
        function: functionName,
        region = emulators.functions.region,
      }) =&gt; [
        `/${functionName}`,
        {
          target: EMULATORS_ACTIVE
            ? `http://localhost:${emulators.functions.port}/${projectId}/${region}/${functionName}`
            : `https://${region}-${projectId}.cloudfunctions.net/${functionName}`,
          changeOrigin: true,
          rewrite: (path) =&gt; path.replace(globToRegExp(source), &quot;&quot;),
        } satisfies ProxyOptions,
      ]
    )
);
const server = EMULATORS_ACTIVE
  ? {
      proxy: functionRewrites,
    }
  : undefined;

export default defineConfig({
  // ...
  server
})
</code></pre>

