Q: Compute sin(x)-x efficiently to double precision accuracy on range |x| &lt;= pi A: <p>There are obvious trade-offs between accuracy and efficiency here. As opposed to the computation of exp(x)-1, where the most significant term is 0.5*x, which can be computer error free in binary floating-point arithmetic, the most significant term in computing sin(x)-x is 0.16666666666666666*x<sup>3</sup>, which incurs a maximum error of 2 ulps when performed in pure double-precision computation, so we are looking at a maximum error of <em>at least</em> 2.5 ulps for computing sin(x)-x in pure double-precision arithmetic. Accuracy can be addressed by local use of (simulated) higher precision computation of intermediate terms, at the expense of efficiency.</p>
<p>For the code below I am assuming that efficiency is the primary goal as this function is called billions of times as part of astronomical simulations, and that we therefore desire to maximize instruction-level parallelism for best performance on wide out-of-order architectures, such as high-end x86-64 and ARM64 platforms. The actual impact on performance depends on the degree of parallelization provided by the FPU hardware as well as the general code context in which the function is called.</p>
<p>The principal tool used here is the use of a partial, two-way, parallelization of the Horner scheme used for the evaluation of polynomials. In the literature this is called a <em>second-order</em> Horner scheme. Various arrangements are possible and I picked one based on my prior math library implementation experience.</p>
<p>Since one would like to improve efficiency with as little negative impact on accuracy as possible, I established a baseline by using the <code>E_sinE_Poly11()</code> function from asker's <a href="https://stackoverflow.com/a/79884522/780717">self-answer</a>. My test framework used a multi-precision library configured for 250-bit accuracy as the golden reference. I observed the following accuracy metrics by applying one billion random test vectors uniformly distributed in [-π, π]: maximum error of 3.50 ulps, maximum relative error of 4.76e-16, with 48.6% of results correctly rounded.</p>
<p>I used my own implementation of the Remes algorithm to find a basic set of coefficients for a minimax polynomial approximation. I then <em>lightly</em> tuned the coefficient set with a heuristic lattice search of my own design, for platforms with and without support for FMA (fused multiply-add). The accuracy without FMA is <em>roughly</em> in line with the baseline reference: maximum error of 3.55 ulps, maximum relative error of 5.16e16, with 54.1% of results correctly rounded. The use of FMA helps to improve accuracy significantly so it closely approaches the a-priori estimate: maximum error of 2.63 ulps, maximum relative error of 3.94e-16, and 62.6% of results correctly rounded.</p>
<pre class="lang-c prettyprint-override"><code>#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;stdint.h&gt;
#include &lt;string.h&gt;
#include &lt;inttypes.h&gt;
#include &lt;math.h&gt;

#define TEST_SIN_E_POLY11 (0)
#define USE_FMA           (0)
#define N                 (100000000)
#define LIMIT             (3.14159265358979323)

/*
   Compute sin(x) - x. With 1 billion random test vectors uniformly distributed in [-pi,+pi]:

   USE_FMA=0:
   maxulperr=3.54786708     @ 2.5048123110639549
   maxrelerr=5.12236881e-16 @ 2.8406512751421205
   diffsum=487288324 correctly_rounded=541095431

   USE_FMA=1:
   maxulperr=2.63086272     @ -8.9995839209370126e-2  
   maxrelerr=3.93839445e-16 @  2.9786700960199712
   diffsum=381159187 correctly_rounded=626007973
*/
double sin_x_minus_x (double x)
{
    double x2, x4, p, q, r;

    x2 = x * x;
    x4 = x2 * x2;
#if USE_FMA
    p =              0x1.5236977c85918p-66;  //  1.7904860318766536e-20
    q =             -0x1.2e2742e344af9p-57;  // -8.1898833520153851e-18
    p = fma (p, x4,  0x1.952126d195c4bp-49); //  2.8111506079635653e-15 
    q = fma (q, x4, -0x1.ae7efcdd21f31p-41); // -7.6471459546101301e-13
    p = fma (p, x4,  0x1.6124605c24f11p-33); //  1.6059043234053136e-10
    q = fma (q, x4, -0x1.ae64567c0727bp-26); // -2.5052108373987793e-8
    p = fma (p, x4,  0x1.71de3a5566104p-19); //  2.7557319223875101e-6
    q = fma (q, x4, -0x1.a01a01a019f50p-13); // -1.9841269841269294e-4
    p = fma (p, x4,  0x1.111111111110dp-7);  //  8.3333333333333263e-3
    p = fma (q, x2, p);
    r = fma (-0x1.5555555555555p-3, x2, p * x4); // -1.6666666666666666e-1
#else // !USE_FMA
    p =          0x1.5236977c85b7ep-66; //  1.7904860318768383e-20
    q =        - 0x1.2e2742e344a39p-57; // -8.1898833520150893e-18
    p = p * x4 + 0x1.952126d195cfep-49; //  2.8111506079636359e-15
    q = q * x4 - 0x1.ae7efcdd21f29p-41; // -7.6471459546101220e-13
    p = p * x4 + 0x1.6124605c24f08p-33; //  1.6059043234053113e-10
    q = q * x4 - 0x1.ae64567c07287p-26; // -2.5052108373987833e-8
    p = p * x4 + 0x1.71de3a556610cp-19; //  2.7557319223875134e-6
    q = q * x4 - 0x1.a01a01a019f53p-13; // -1.9841269841269302e-4
    p = p * x4 + 0x1.111111111110dp-7;  //  8.3333333333333263e-3
    p = q * x2 + p;
    r = (-0x1.5555555555555p-3 * x2) + (p * x4); // -1.6666666666666666e-1
#endif // USE_FMA
    r = r * x;
    return r;
}

/* 
   https://stackoverflow.com/a/79884522/780717
   With 1 billion random test vectors uniformly distributed in [-pi,+pi]:
   maxulperr=3.49687072     @ -2.5477100738613370
   maxrelerr=4.75864380e-16 @ -2.0012212744695566
   diffsum=559630555 correctly_rounded=485646547
*/
double E_sinE_Poly11(double x)
{
    double x2 = x * x;
    return x * x2 * ((0.1666666666666666666635343 + x2 * (-0.00833333333333333325969919500 + x2 * (0.00019841269841269812444987753472416294252 + x2 * (-2.7557319223981464666449786883331e-06 + x2 * (2.50521083850916067252611970e-08 + x2 * (-1.6059043820604558885264159359e-10 + x2 * (7.6471632620001400312567764600456792e-13 + x2 * (-2.81144848619712977940552238279545e-15 + x2 * (8.2195805249818220533910112292571468e-18 + x2 * (-1.9493800527350709659097526622973723e-20 + x2 * (3.52962467036068327222028588962499e-23))))))))))));
}

// interface to Brent's MP library; in a private header file in reality
struct mpNum {/* obviously non-null in reality */};
void mpInit (void);
void mpSub (struct mpNum *, struct mpNum *, struct mpNum *);
void mpDiv (struct mpNum *, struct mpNum *, struct mpNum *);
void mpAbs (struct mpNum *, struct mpNum *);
void mpSin (struct mpNum *, struct mpNum *);
void mpDoubleToMp (double, struct mpNum *);
void mpMpToDouble (struct mpNum *, double *);
double doubleUlpErr (double, struct mpNum *);

/*
  https://groups.google.com/forum/#!original/comp.lang.c/qFv18ql_WlU/IK8KGZZFJx4J
  From: geo &lt;gmars...@gmail.com&gt;
  Newsgroups: sci.math,comp.lang.c,comp.lang.fortran
  Subject: 64-bit KISS RNGs
  Date: Sat, 28 Feb 2009 04:30:48 -0800 (PST)

  This 64-bit KISS RNG has three components, each nearly
  good enough to serve alone.    The components are:
  Multiply-With-Carry (MWC), period (2^121+2^63-1)
  Xorshift (XSH), period 2^64-1
  Congruential (CNG), period 2^64
*/
static uint64_t kiss64_x = 1234567890987654321ULL;
static uint64_t kiss64_c = 123456123456123456ULL;
static uint64_t kiss64_y = 362436362436362436ULL;
static uint64_t kiss64_z = 1066149217761810ULL;
static uint64_t kiss64_t;
#define MWC64  (kiss64_t = (kiss64_x &lt;&lt; 58) + kiss64_c, \
                kiss64_c = (kiss64_x &gt;&gt; 6), kiss64_x += kiss64_t, \
                kiss64_c += (kiss64_x &lt; kiss64_t), kiss64_x)
#define XSH64  (kiss64_y ^= (kiss64_y &lt;&lt; 13), kiss64_y ^= (kiss64_y &gt;&gt; 17), \
                kiss64_y ^= (kiss64_y &lt;&lt; 43))
#define CNG64  (kiss64_z = 6906969069ULL * kiss64_z + 1234567ULL)
#define KISS64 (MWC64 + XSH64 + CNG64)

uint64_t double_as_uint64 (double a)
{
    uint64_t r;
    memcpy (&amp;r, &amp;a, sizeof r);
    return r;
}

double uint64_as_double (uint64_t a)
{
    double r;
    memcpy (&amp;r, &amp;a, sizeof r);
    return r;
}

int main (void)
{
    mpInit();

    struct mpNum mpArg, mpRes, mpRef, mpErr;
    double res, ref, ulperr, relerr, maxulperr, maxrelerr;
    double relerrloc = NAN, ulperrloc = NAN;
    uint64_t diffsum, correctly_rounded;

    maxrelerr = 0;
    maxulperr = 0;
    diffsum = 0;
    correctly_rounded = 0;
    for (int i = 0; i &lt; N; i++) {
        uint64_t t = KISS64;
        double arg = (0x1.0p-63 * LIMIT) * ((int64_t) t);
        mpDoubleToMp (arg, &amp;mpArg);
        mpSin (&amp;mpArg, &amp;mpRef);
        mpSub (&amp;mpRef, &amp;mpArg, &amp;mpRef);
        mpMpToDouble (&amp;mpRef, &amp;ref);

#if TEST_SIN_E_POLY11        
        res = E_sinE_Poly11 (-arg);
#else // !TEST_SIN_E_POLY11 
        res = sin_x_minus_x (arg);
#endif // TEST_SIN_E_POLY11  

        mpDoubleToMp (res, &amp;mpRes);
        ulperr = doubleUlpErr (res, &amp;mpRef);
        if (ulperr &gt; maxulperr) {
            maxulperr = ulperr;
            ulperrloc = arg;
        }
        mpSub (&amp;mpRes, &amp;mpRef, &amp;mpErr);
        mpDiv (&amp;mpErr, &amp;mpRef, &amp;mpErr);
        mpAbs (&amp;mpErr, &amp;mpErr);
        mpMpToDouble (&amp;mpErr, &amp;relerr);
        if (relerr &gt; maxrelerr) {
            maxrelerr = relerr;
            relerrloc = arg;
        }
        uint64_t ires = double_as_uint64 (res);
        uint64_t iref = double_as_uint64 (ref);
        uint64_t diff = (ires &gt; iref) ? (ires - iref) : (iref - ires);
        correctly_rounded += (diff == 0);
        if (diff &gt; 5) {
            printf (&quot;!!!! diff=%&quot;PRIu64&quot; @ arg = % 23.16e res=%23.13a ref=%23.13a\n&quot;,
                    diff, arg, res, ref);
            return EXIT_FAILURE;
        }
        diffsum += diff;
    }
    printf (&quot;\nmaxulperr=%15.8e @ %23.16e  maxrelerr=%15.8e @ %23.16e  diffsum=%&quot;PRIu64&quot; correctly_rounded=%&quot;PRIu64&quot;\n&quot;, 
            maxulperr, ulperrloc, maxrelerr, relerrloc, diffsum, correctly_rounded);
    return EXIT_SUCCESS;
}
</code></pre>
